package finance.network;
import finance.governance.*;import net.minecraft.network.FriendlyByteBuf;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.fml.DistExecutor;import net.minecraftforge.network.NetworkEvent;import java.util.*;import java.util.function.Supplier;
public record GovernanceResponsePacket(long requestId,UUID companyId,long totalShares,long votingShares,long treasuryShares,long systemLiquidity,List<HolderRow>holders,List<ActionRow>actions,CompanyValuationService.Summary valuation,CapitalStructureService.Summary structure,UUID controller){public static final int MAX_ROWS=64;public record HolderRow(UUID id,long shares,long locked,double ownership,double voting){}public record ActionRow(UUID id,String type,CapitalActionStatus status,long price,long shares,long endDay){}public GovernanceResponsePacket{holders=List.copyOf(holders.subList(0,Math.min(MAX_ROWS,holders.size())));actions=List.copyOf(actions.subList(0,Math.min(MAX_ROWS,actions.size())));}public static void encode(GovernanceResponsePacket p,FriendlyByteBuf b){b.writeLong(p.requestId);b.writeUUID(p.companyId);b.writeLong(p.totalShares);b.writeLong(p.votingShares);b.writeLong(p.treasuryShares);b.writeLong(p.systemLiquidity);b.writeVarInt(p.holders.size());for(var x:p.holders){b.writeUUID(x.id);b.writeLong(x.shares);b.writeLong(x.locked);b.writeDouble(x.ownership);b.writeDouble(x.voting);}b.writeVarInt(p.actions.size());for(var x:p.actions){b.writeUUID(x.id);b.writeUtf(x.type,16);b.writeEnum(x.status);b.writeLong(x.price);b.writeLong(x.shares);b.writeLong(x.endDay);}var v=p.valuation;for(long x:new long[]{v.day(),v.bookAssets(),v.liabilities(),v.bookEquity(),v.averageProfit(),v.earningsValue(),v.marketCap(),v.enterpriseValue(),v.inventoryValue(),v.operatingAssetValue()})b.writeLong(x);b.writeUtf(v.quality(),32);b.writeUtf(v.riskAdjustment(),128);var z=p.structure;for(long x:new long[]{z.cash(),z.operatingAssets(),z.bankAndOtherLoans(),z.bonds(),z.totalShares(),z.votingShares(),z.treasuryShares(),z.marketCap(),z.enterpriseValue(),z.insuredCredit(),z.nearTermDebt()})b.writeLong(x);b.writeVarInt(z.financingProjects());b.writeVarInt(z.buybacks());b.writeVarInt(z.tenders());b.writeBoolean(p.controller!=null);if(p.controller!=null)b.writeUUID(p.controller);}public static GovernanceResponsePacket decode(FriendlyByteBuf b){long request=b.readLong();UUID company=b.readUUID();long total=b.readLong(),voting=b.readLong(),treasury=b.readLong(),system=b.readLong();int n=count(b);List<HolderRow>h=new ArrayList<>(n);for(int i=0;i<n;i++)h.add(new HolderRow(b.readUUID(),b.readLong(),b.readLong(),b.readDouble(),b.readDouble()));n=count(b);List<ActionRow>a=new ArrayList<>(n);for(int i=0;i<n;i++)a.add(new ActionRow(b.readUUID(),b.readUtf(16),b.readEnum(CapitalActionStatus.class),b.readLong(),b.readLong(),b.readLong()));long[]v=new long[10];for(int i=0;i<v.length;i++)v[i]=b.readLong();var val=new CompanyValuationService.Summary(v[0],v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],b.readUtf(32),b.readUtf(128));long[]z=new long[11];for(int i=0;i<z.length;i++)z[i]=b.readLong();var structure=new CapitalStructureService.Summary(z[0],z[1],z[2],z[3],z[4],z[5],z[6],z[7],z[8],z[9],z[10],b.readVarInt(),b.readVarInt(),b.readVarInt());return new GovernanceResponsePacket(request,company,total,voting,treasury,system,h,a,val,structure,b.readBoolean()?b.readUUID():null);}private static int count(FriendlyByteBuf b){int n=b.readVarInt();if(n<0||n>MAX_ROWS)throw new IllegalArgumentException("governance rows");return n;}public static void handle(GovernanceResponsePacket p,Supplier<NetworkEvent.Context>s){var c=s.get();c.enqueueWork(()->DistExecutor.unsafeRunWhenOn(Dist.CLIENT,()->()->finance.client.GovernanceClientCache.accept(p)));c.setPacketHandled(true);}}
